function numberingXML(count) {
  const bullet = '<w:abstractNum w:abstractNumId="0"><w:multiLevelType w:val="singleLevel"/>'
    + '<w:lvl w:ilvl="0"><w:start w:val="1"/><w:numFmt w:val="bullet"/><w:lvlText w:val="\u2022"/>'
    + '<w:lvlJc w:val="left"/><w:pPr><w:ind w:left="454" w:hanging="284"/></w:pPr>'
    + '<w:rPr><w:rFonts w:ascii="Georgia" w:hAnsi="Georgia"/></w:rPr></w:lvl></w:abstractNum>';
  const decimal = '<w:abstractNum w:abstractNumId="1"><w:multiLevelType w:val="singleLevel"/>'
    + '<w:lvl w:ilvl="0"><w:start w:val="1"/><w:numFmt w:val="decimal"/><w:lvlText w:val="%1."/>'
    + '<w:lvlJc w:val="left"/><w:pPr><w:ind w:left="454" w:hanging="284"/></w:pPr>'
    + '<w:rPr><w:rFonts w:ascii="Georgia" w:hAnsi="Georgia"/></w:rPr></w:lvl></w:abstractNum>';
  const nums = ['<w:num w:numId="1"><w:abstractNumId w:val="0"/></w:num>'];
  for (let i = 0; i < count; i += 1) {
    nums.push(`<w:num w:numId="${100 + i}"><w:abstractNumId w:val="1"/>`
      + '<w:lvlOverride w:ilvl="0"><w:startOverride w:val="1"/></w:lvlOverride></w:num>');
  }
  return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
    + '<w:numbering xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">'
    + bullet + decimal + nums.join('') + '</w:numbering>';
}

function footerXML() {
  return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
    + '<w:ftr xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">'
    + '<w:p><w:pPr><w:jc w:val="center"/><w:spacing w:before="0" w:after="0"/></w:pPr>'
    + '<w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="18"/><w:color w:val="615A52"/></w:rPr>'
    + '<w:fldChar w:fldCharType="begin"/></w:r>'
    + '<w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="18"/><w:color w:val="615A52"/></w:rPr>'
    + '<w:instrText xml:space="preserve"> PAGE </w:instrText></w:r>'
    + '<w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="18"/><w:color w:val="615A52"/></w:rPr>'
    + '<w:fldChar w:fldCharType="separate"/></w:r>'
    + '<w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="18"/><w:color w:val="615A52"/></w:rPr><w:t>1</w:t></w:r>'
    + '<w:r><w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial"/><w:sz w:val="18"/><w:color w:val="615A52"/></w:rPr>'
    + '<w:fldChar w:fldCharType="end"/></w:r></w:p></w:ftr>';
}

/* ----------------------------------------------------------------- main ---- */

const html = fs.readFileSync(SRC, 'utf8');
const body = html.slice(html.indexOf('<body'), html.indexOf('</body>'));
const tree = parseHTML(body);
const sections = [];
(function collect(node) {
  for (const child of kids(node)) {
    if (child.name === 'section' && hasClass(child, 'page')) { sections.push(child); continue; }
    if (child.name === '#text') continue;
    collect(child);
  }
})(tree);

let documentBody = '';
sections.forEach((section, index) => {
  documentBody += renderBlocks(kids(section), { pageBreakBefore: index > 0 });
});

const sectPr = '<w:sectPr>'
  + '<w:footerReference w:type="default" r:id="rIdFooter1"/>'
  + `<w:pgSz w:w="${A4_W}" w:h="${A4_H}"/>`
  + `<w:pgMar w:top="${MARGIN}" w:right="${MARGIN}" w:bottom="${MARGIN}" w:left="${MARGIN}" `
  + 'w:header="709" w:footer="709" w:gutter="0"/>'
  + '<w:cols w:space="708"/><w:docGrid w:linePitch="360"/></w:sectPr>';

const documentXML = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
  + '<w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" '
  + 'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" '
  + 'xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" '
  + 'xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
  + 'xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture">'
  + `<w:body>${documentBody}${sectPr}</w:body></w:document>`;

const imageRels = images.map((img) => `<Relationship Id="${img.relId}" `
  + 'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" '
  + `Target="media/${img.name}"/>`).join('');

const documentRels = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
  + '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
  + '<Relationship Id="rIdStyles" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>'
  + '<Relationship Id="rIdNumbering" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/numbering" Target="numbering.xml"/>'
  + '<Relationship Id="rIdSettings" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/settings" Target="settings.xml"/>'
  + '<Relationship Id="rIdFooter1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/footer" Target="footer1.xml"/>'
  + imageRels
  + '</Relationships>';

const contentTypes = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
  + '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
  + '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
  + '<Default Extension="xml" ContentType="application/xml"/>'
  + '<Default Extension="png" ContentType="image/png"/>'
  + '<Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>'
  + '<Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/>'
  + '<Override PartName="/word/numbering.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.numbering+xml"/>'
  + '<Override PartName="/word/settings.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.settings+xml"/>'
  + '<Override PartName="/word/footer1.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.footer+xml"/>'
  + '<Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/>'
  + '<Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/>'
  + '</Types>';

const rootRels = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
  + '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
  + '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>'
  + '<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/>'
  + '<Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties" Target="docProps/app.xml"/>'
  + '</Relationships>';

const now = new Date().toISOString().replace(/\.\d+Z$/, 'Z');
const core = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
  + '<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" '
  + 'xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" '
  + 'xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">'
  + '<dc:title>Iṣẹ́: A Blind, Explainable and Auditable Graduate CV Screening Platform for Nigerian Employers</dc:title>'
  + '<dc:subject>B.Sc. Computer Science project report, University of Lagos</dc:subject>'
  + '<dc:creator>Department of Computer Science, University of Lagos</dc:creator>'
  + `<dcterms:created xsi:type="dcterms:W3CDTF">${now}</dcterms:created>`
  + `<dcterms:modified xsi:type="dcterms:W3CDTF">${now}</dcterms:modified>`
  + '</cp:coreProperties>';

const app = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
  + '<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties">'
  + '<Application>Microsoft Office Word</Application><Words>0</Words></Properties>';

const settings = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
  + '<w:settings xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">'
  + '<w:zoom w:percent="100"/><w:defaultTabStop w:val="708"/>'
  + '<w:updateFields w:val="true"/><w:autoHyphenation w:val="true"/>'
  + '<w:hyphenationZone w:val="284"/><w:characterSpacingControl w:val="doNotCompress"/>'
  + '<w:compat><w:compatSetting w:name="compatibilityMode" '
  + 'w:uri="http://schemas.microsoft.com/office/word" w:val="15"/></w:compat>'
  + '</w:settings>';

const zip = new JSZip();
zip.file('[Content_Types].xml', contentTypes);
zip.file('_rels/.rels', rootRels);
zip.file('docProps/core.xml', core);
zip.file('docProps/app.xml', app);
zip.file('word/document.xml', documentXML);
zip.file('word/styles.xml', stylesXML());
zip.file('word/numbering.xml', numberingXML(orderedListCount));
zip.file('word/settings.xml', settings);
zip.file('word/footer1.xml', footerXML());
zip.file('word/_rels/document.xml.rels', documentRels);
for (const img of images) zip.file(`word/media/${img.name}`, img.buf);

const buffer = await zip.generateAsync({
  type: 'nodebuffer',
  compression: 'DEFLATE',
  compressionOptions: { level: 6 },
});
fs.writeFileSync(OUT, buffer);

const words = (documentBody.replace(/<[^>]+>/g, ' ').match(/\S+/g) ?? []).length;
console.log(`wrote ${path.relative(process.cwd(), OUT)} (${(buffer.length / 1024).toFixed(0)} KB)`);
console.log(`sections=${sections.length} images=${images.length} orderedLists=${orderedListCount} words~${words}`);
